        d_gp = get_surface_distance(er, ep, distance_metric='euclidean', spacing=sp)
        data[name] = (ep, er, d_pg, d_gp, sp)

def exposed(mask):
    mask=mask.astype(bool); ndim=mask.ndim
    faces=[np.zeros(mask.shape,float) for _ in range(ndim)]
    for axis in range(ndim):
        s=[slice(None)]*ndim; sp_=[slice(None)]*ndim
        s[axis]=slice(1,None); sp_[axis]=slice(None,-1)
        fwd = mask[tuple(s)] & ~mask[tuple(sp_)]
        bwd = mask[tuple(sp_)] & ~mask[tuple(s)]
        other=[1.0]*ndim; other[axis]=0
        faces[axis][tuple(s)] += np.where(fwd,1.0,0)
        faces[axis][tuple(sp_)] += np.where(bwd,1.0,0)
    return faces  # list of per-axis face-count arrays

def nsd(name, wp_func, wg_func):
    ep,er,d_pg,d_gp,sp = data[name]
    wp = wp_func(ep, sp); wg = wg_func(er, sp)
    wp_v = wp[ep]; wg_v = wg[er]
    Mp = wp_v.sum(); Mg = wg_v.sum()
    Mp_in = wp_v[d_pg<=tol].sum(); Mg_in = wg_v[d_gp<=tol].sum()
    return (Mp_in+Mg_in)/(Mp+Mg)

# Convention: face-count area (perp-to-axis area = prod of other spacings)
def area_w(mask, sp):
    fs = exposed(mask); ndim=mask.ndim
    w = np.zeros(mask.shape, float)
    for axis in range(ndim):
        other = [sp[i] for i in range(ndim) if i"'!=axis]
        w += fs[axis]*float(np.prod(other))
    return w

# weight by spacing along normal axis only (each face = spacing-of-other-axes)... same as area
# weight = count of faces
def count_w(mask, sp):
    fs = exposed(mask); w=sum(fs); return w
# weight = 1 (legacy)
def one_w(mask, sp):
    return mask.astype(float)
# weight = product of all spacings (volume) -- isotropic-ish per voxel
def vol_w(mask, sp):
    return mask.astype(float)*float(np.prod(sp))
# weight = mean spacing per voxel
def mean_w(mask, sp):
    return mask.astype(float)*float(np.mean(sp))
# weight = max spacing
def maxsp_w(mask,sp):
    return mask.astype(float)*float(np.max(sp))
# weight = min spacing
def minsp_w(mask,sp):
    return mask.astype(float)*float(np.min(sp))

convs = {'"'count(one)':one_w,'face_area':area_w,'face_count':count_w,'vol':vol_w,'mean_sp':mean_w,'max_sp':maxsp_w,'min_sp':minsp_w}
